{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useClipboard",
    "displayName": "useClipboard",
    "keywords": [
      "clipboard",
      "copy",
      "copied",
      "paste",
      "writeText",
      "copy-to-clipboard",
      "copy button",
      "announce",
      "a11y"
    ],
    "params": [
      {
        "name": "options",
        "type": "UseClipboardOptions",
        "description": "Configuration object.",
        "required": false
      },
      {
        "name": "options.announce",
        "type": "string",
        "description": "Message announced to a polite live region on a successful copy. A swapped aria-label alone is not reliably announced, so pass the localized confirmation (e.g. \"Copied\") to have it spoken. Omit to skip the announcement.",
        "required": false
      },
      {
        "name": "options.resetAfterMs",
        "type": "number",
        "description": "Milliseconds isCopied stays true after a successful copy before reverting.",
        "default": "2000",
        "required": false
      }
    ],
    "returns": [
      {
        "name": "copy",
        "type": "(text: string) => Promise<boolean>",
        "description": "Writes text to the clipboard. On success flips isCopied to true, announces the configured message, restarts the reset timer, and resolves true. A clipboard rejection is a silent no-op that leaves the copied state unchanged and resolves false."
      },
      {
        "name": "isCopied",
        "type": "boolean",
        "description": "True for resetAfterMs after the most recent successful copy, then reverts. Drive the copied confirmation (e.g. a copy → check icon flip) off this."
      }
    ],
    "usage": {
      "description": "Copy-to-clipboard behavior: the clipboard write, a transient isCopied flag with its own reset timer, and an optional polite screen-reader announcement. Extracted so every copy affordance is a thin control over one implementation instead of re-deriving the timer and announcement. Rapid re-copies restart the reset timer so the confirmation always lasts the full duration, and the timer is cleaned up on unmount. CodeBlock and Timestamp build their built-in copy buttons on it; reach for it directly when building a copy affordance that is not a plain icon button (a menu item, a labeled text button, a copy-on-click value chip).",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Drive the copied confirmation (copy → check icon, label swap) off the returned isCopied flag rather than tracking your own state."
        },
        {
          "guidance": true,
          "description": "Pass a localized announce message so the copy is spoken by screen readers; swapping the button aria-label alone is not reliably announced."
        },
        {
          "guidance": true,
          "description": "For the common compact icon copy button, render a ghost IconButton with a \"Copy\" tooltip and wire onClick to copy(); the tooltip stays \"Copy\" and the icon flip is the confirmation."
        },
        {
          "guidance": false,
          "description": "Track a separate copied useState alongside the hook; isCopied already reflects the copied window and resets itself."
        }
      ]
    },
    "relatedComponents": [
      "CodeBlock",
      "Timestamp",
      "IconButton"
    ],
    "relatedHooks": [
      "useAnnounce"
    ],
    "importPath": "@astryxdesign/core/hooks",
    "category": "interaction"
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.4.7",
      "copy": "starting"
    }
  }
}
